use crate::util;
use serde_json::{json,Value};
use std::sync::{Mutex,atomic::{AtomicU64,Ordering}};
use tauri::{AppHandle,Emitter};
static GENERATION:AtomicU64=AtomicU64::new(0);
static PAIR:Mutex<Option<(String,std::time::Instant)>>=Mutex::new(None);
static SECRET:Mutex<()>=Mutex::new(());
pub fn init(_app:&AppHandle){}
fn authorised(owner:i64,from:&Value,chat:&Value)->bool{owner>0&&from["id"]==owner&&chat["type"]=="private"&&chat["id"]==owner}

fn token()->Result<String,String>{let text=std::fs::read_to_string(util::data_dir().join(".env")).unwrap_or_default();text.lines().find_map(|l|l.strip_prefix("TELEGRAM_BOT_TOKEN=").and_then(|v|serde_json::from_str::<String>(v).ok())).filter(|s|!s.is_empty()).ok_or("Не настроен токен Telegram".into())}
async fn api(method:&str,body:Value)->Result<Value,String>{let token=token()?;let client=util::http_builder().redirect(reqwest::redirect::Policy::none()).timeout(std::time::Duration::from_secs(35)).build().map_err(|_|"Ошибка HTTP")?;let response=client.post(format!("https://api.telegram.org/bot{token}/{method}")).json(&body).send().await.map_err(|_|"Telegram недоступен")?;if !response.status().is_success(){return Err("Telegram отклонил запрос".into());}let value:Value=response.json().await.map_err(|_|"Неверный ответ Telegram")?;if value["ok"]!=true{return Err("Ошибка Telegram API".into());}Ok(value["result"].clone())}
async fn download(file_id:&str,extension:&str)->Result<String,String>{let info=api("getFile",json!({"file_id":file_id})).await?;let path=info["file_path"].as_str().filter(|s|s.len()<1000&&!s.starts_with('/')&&!s.split('/').any(|p|p=="..")&&!s.contains(['\\','?','#'])).ok_or("Неверный путь файла Telegram")?;let client=util::http_builder().redirect(reqwest::redirect::Policy::none()).timeout(std::time::Duration::from_secs(45)).build().map_err(|_|"Ошибка HTTP")?;let mut response=client.get(format!("https://api.telegram.org/file/bot{}/{path}",token()?)).send().await.map_err(|_|"Не удалось скачать файл")?;if !response.status().is_success(){return Err("Файл Telegram недоступен".into());}let mut bytes=vec![];while let Some(chunk)=response.chunk().await.map_err(|_|"Файл Telegram оборвался")?{if bytes.len()+chunk.len()>20*1024*1024{return Err("Файл Telegram больше 20 МБ".into());}bytes.extend_from_slice(&chunk);}let ext=if !extension.is_empty()&&extension.len()<12&&extension.bytes().all(|b|b.is_ascii_alphanumeric()){extension}else{"bin"};let target=util::data_dir().join("attachments").join(format!("tg-{}.{}",uuid::Uuid::new_v4(),ext));util::atomic_write(&target,&bytes)?;Ok(target.to_string_lossy().into())}
pub async fn call(app:&AppHandle,method:&str,a:Value)->Result<Value,String>{match method{
"state"=>Ok(json!({"configured":token().is_ok(),"enabled":util::setting("tgEnabled"),"owner":util::setting("tgOwner"),"pairCode":PAIR.lock().unwrap().as_ref().map(|p|p.0.clone())})),
"configure"=>{GENERATION.fetch_add(1,Ordering::SeqCst);util::set_setting("tgEnabled",json!(false));let _g=SECRET.lock().unwrap();let _env=util::ENV.lock().unwrap();let owner=a["owner"].as_i64().filter(|n|*n>=0).ok_or("Некорректный user ID")?;let value=a["token"].as_str().unwrap_or_default().trim();if value.len()>300||!value.bytes().all(|b|b.is_ascii_alphanumeric()||b==b':'||b==b'_'||b==b'-'){return Err("Некорректный токен".into());}let file=util::data_dir().join(".env");let old=std::fs::read_to_string(&file).unwrap_or_default();let mut lines:Vec<_>=old.lines().filter(|l|!l.starts_with("TELEGRAM_BOT_TOKEN=")).map(str::to_string).collect();if !value.is_empty(){lines.push(format!("TELEGRAM_BOT_TOKEN={}",json!(value)));}util::atomic_write(&file,(lines.join("\n")+"\n").as_bytes())?;util::set_setting("tgOwner",if owner>0{json!(owner)}else{Value::Null});util::set_setting("tgOffset",json!(0));Ok(Value::Null)},
"pair"=>{let code=format!("{:06}",u32::from_le_bytes(uuid::Uuid::new_v4().as_bytes()[..4].try_into().unwrap())%1_000_000);*PAIR.lock().unwrap()=Some((code.clone(),std::time::Instant::now()));util::set_setting("tgOwner",Value::Null);Ok(json!({"code":code}))},
"unpair"=>{GENERATION.fetch_add(1,Ordering::SeqCst);util::set_setting("tgOwner",Value::Null);util::set_setting("tgEnabled",json!(false));*PAIR.lock().unwrap()=None;Ok(Value::Null)},
"stop"=>{GENERATION.fetch_add(1,Ordering::SeqCst);util::set_setting("tgEnabled",json!(false));Ok(Value::Null)},
"start"=>{token()?;if util::setting("tgOwner").as_i64().unwrap_or(0)<=0&&PAIR.lock().unwrap().is_none(){return Err("Сначала создай код привязки".into());}let run=GENERATION.fetch_add(1,Ordering::SeqCst)+1;util::set_setting("tgEnabled",json!(true));let app=app.clone();tokio::spawn(async move{let mut offset=util::setting("tgOffset").as_i64().unwrap_or(0);while GENERATION.load(Ordering::SeqCst)==run{match api("getUpdates",json!({"offset":offset,"timeout":25,"allowed_updates":["message","callback_query"]})).await{Ok(rows)=>{for row in rows.as_array().into_iter().flatten(){if GENERATION.load(Ordering::SeqCst)!=run{break;}offset=offset.max(row["update_id"].as_i64().unwrap_or(0)+1);util::set_setting("tgOffset",json!(offset));
let q=&row["callback_query"];if q.is_object(){if authorised(util::setting("tgOwner").as_i64().unwrap_or(0),&q["from"],&q["message"]["chat"]){let _=app.emit("telegram",json!({"callback":q["data"]}));let _=api("answerCallbackQuery",json!({"callback_query_id":q["id"]})).await;}continue;}
let m=&row["message"];if util::setting("tgOwner").as_i64().unwrap_or(0)==0&&m["chat"]["type"]=="private"&&m["from"]["id"]==m["chat"]["id"]{let incoming=m["text"].as_str().unwrap_or_default().trim().trim_start_matches("/start").trim();let paired={let mut pair=PAIR.lock().unwrap();if pair.as_ref().is_some_and(|(code,time)|time.elapsed().as_secs()<600&&code==incoming){*pair=None;true}else{false}};if paired{util::set_setting("tgOwner",m["from"]["id"].clone());let _=app.emit("telegram",json!({"paired":true}));}continue;}
if authorised(util::setting("tgOwner").as_i64().unwrap_or(0),&m["from"],&m["chat"])&&GENERATION.load(Ordering::SeqCst)==run{let file=m["photo"].as_array().and_then(|p|p.last()).and_then(|p|p["file_id"].as_str()).map(|id|(id,"jpg".to_string())).or_else(||m["document"]["file_id"].as_str().map(|id|(id,m["document"]["file_name"].as_str().and_then(|n|n.rsplit('.').next()).unwrap_or("bin").to_string())));let attachment=if let Some((id,ext))=file{match download(id,&ext).await{Ok(path)=>Some(path),Err(error)=>{let _=app.emit("telegram",json!({"error":error}));continue;}}}else{None};if GENERATION.load(Ordering::SeqCst)==run{let _=app.emit("telegram",json!({"text":m["text"].as_str().or(m["caption"].as_str()).unwrap_or(""),"attachment":attachment,"chat":m["chat"]["id"]}));}}}},Err(_)=>tokio::time::sleep(std::time::Duration::from_secs(5)).await}}});Ok(Value::Null)},
"send"=>{if util::setting("tgEnabled")!=true{return Err("Telegram выключен".into());}let text=a["text"].as_str().ok_or("Нет текста")?;let owner=util::setting("tgOwner");for chunk in text.chars().collect::<Vec<_>>().chunks(3500){api("sendMessage",json!({"chat_id":owner,"text":chunk.iter().collect::<String>(),"reply_markup":a["reply_markup"]})).await?;}Ok(Value::Null)},_=>Err("Неизвестный метод Telegram".into())}}

#[cfg(test)]mod tests{use super::*;#[test]fn callbacks_and_messages_require_same_private_owner(){assert!(authorised(42,&json!({"id":42}),&json!({"id":42,"type":"private"})));assert!(!authorised(0,&json!({"id":0}),&json!({"id":0,"type":"private"})));assert!(!authorised(42,&json!({"id":7}),&json!({"id":42,"type":"private"})));assert!(!authorised(42,&json!({"id":42}),&json!({"id":7,"type":"private"})));assert!(!authorised(42,&json!({"id":42}),&json!({"id":42,"type":"group"})));}}
